    /* About Dialog */
    "dlg.about.title": {
      en: "About Solacut",
      zh: "关于 Solacut",
      ja: "Solacut について",
      ko: "Solacut 정보",
      ru: "О Solacut",
      es: "Acerca de Solacut",
    },
    "dlg.about.subtitle": {
      en: "Local long-form VOD clipping and multi-language subtitle workbench (DaVinci / Premiere / FCP)",
      zh: "本地长录屏剪辑与多语种字幕工作台",
      ja: "ローカル長時間録画の編集・多言語字幕ワークベンチ",
      ko: "로컬 장시간 녹화 편집 및 다국어 자막 워크벤치",
      ru: "Локальный инструмент для нарезки длинных записей и подготовки субтитров",
      es: "Mesa de trabajo local para recorte de grabaciones largas y subtítulos multilingües",
    },
    "dlg.about.listHtml": {
      en: "<li><strong>Version &amp; License</strong>: v0.9.4 · MIT License (open-source, no telemetry)</li><li><strong>Languages &amp; Corpus</strong>: EN / ZH / JA / KO / RU / ES 6×6 pairs, built-in 228,210 openly licensed bilingual reference pairs (MIT / CC BY / CC BY-SA)</li><li><strong>Local Security</strong>: Binds to 127.0.0.1 loopback with per-launch 256-bit session token, CSRF &amp; DNS Rebinding checks; source videos remain local</li><li><strong>Website</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Repository</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      zh: "<li><strong>版本与协议</strong>：v0.9.4 · MIT License（开源软件，无遥测采集）</li><li><strong>语料支持</strong>：支持中 / 英 / 日 / 韩 / 俄 / 西 6 语种互译，内置 228,210 条开放许可双语参考语料（MIT / CC BY / CC BY-SA）</li><li><strong>本地安全</strong>：仅绑定 127.0.0.1 回环地址并校验 256-bit 会话令牌，防御跨站及 DNS Rebinding；原始视频保留本地</li><li><strong>官方网站</strong>：<a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>开源仓库</strong>：<a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ja: "<li><strong>バージョンとライセンス</strong>: v0.9.4 · MIT License（オープンソース・テレメトリなし）</li><li><strong>対応言語とコーパス</strong>: 英/中/日/韓/露/西 6×6翻訳、オープンライセンス対訳コーパス 228,210件内蔵（MIT / CC BY / CC BY-SA）</li><li><strong>ローカルセキュリティ</strong>: 127.0.0.1限定バインド + 256-bitセッショントークン + DNS Rebinding防御、元動画はローカルに保持</li><li><strong>公式サイト</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>リポジトリ</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ko: "<li><strong>버전 및 라이선스</strong>: v0.9.4 · MIT License (오픈소스, 텔레메트리 없음)</li><li><strong>언어 및 코퍼스</strong>: 영/중/일/한/러/스 6×6 조합, 오픈 라이선스 병렬 참고 코퍼스 228,210쌍 내장 (MIT / CC BY / CC BY-SA)</li><li><strong>로컬 보안</strong>: 127.0.0.1 루프백 바인딩 + 256비트 세션 토큰 + CSRF/DNS 리바인딩 차단, 원본 영상 로컬 유지</li><li><strong>공식 사이트</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>오픈소스 저장소</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      ru: "<li><strong>Версия и лицензия</strong>: v0.9.4 · MIT License (открытый код, без телеметрии)</li><li><strong>Языки и корпус</strong>: пары EN / ZH / JA / KO / RU / ES (6×6), встроенный справочный корпус из 228 210 пар с открытыми лицензиями (MIT / CC BY / CC BY-SA)</li><li><strong>Безопасность</strong>: привязка к 127.0.0.1, 256-битный токен и защита от CSRF / DNS Rebinding; исходное видео остаётся локально</li><li><strong>Сайт</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Репозиторий</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
      es: "<li><strong>Versión y licencia</strong>: v0.9.4 · MIT License (código abierto, sin telemetría)</li><li><strong>Idiomas y corpus</strong>: pares EN / ZH / JA / KO / RU / ES (6×6), 228.210 pares bilingües de referencia con licencias abiertas (MIT / CC BY / CC BY-SA)</li><li><strong>Seguridad local</strong>: enlace 127.0.0.1, token de 256 bits y protección CSRF / DNS Rebinding; los videos permanecen en local</li><li><strong>Sitio web</strong>: <a href=\"https://solacut.com\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">solacut.com</a></li><li><strong>Repositorio</strong>: <a href=\"https://github.com/Entelina/solacut\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"about-link\">github.com/Entelina/solacut</a></li>",
    },

